import React from 'react';
import TabNav, { TabKey } from './TabNav';

type HeaderProps = {
  active: TabKey;
  onChange: (t: TabKey) => void;
};

export default function Header({ active, onChange }: HeaderProps) {
  return (
    <header className="header" role="navigation" aria-label="Navigation principale">
      <div className="container nav">
        <div className="brand">
          <div className="logo" aria-hidden="true">+</div>
          <span className="brand-name">+Propre</span>
          <span className="badge" title="Couverture Île-de-France">
            Service de nettoyage & d’entretien
          </span>
        </div>

        <TabNav active={active} onChange={onChange} />

        <div className="quick-info">
          <a href="tel:+33765551111">📞 07&nbsp;65&nbsp;55&nbsp;11&nbsp;11</a>
          <span>•</span>
          <a href="mailto:contact@plus-propre.fr">✉️ contact@plus-propre.fr</a>
        </div>
      </div>
    </header>
  );
}
